from pathlib import Path
import json
manifest=json.loads(Path('tools/state-expansion/manifest.json').read_text(encoding='utf8'));animations=json.loads(Path('data/Animations.json').read_text(encoding='utf8'));skills=json.loads(Path('data/Skills.json').read_text(encoding='utf8'));items=json.loads(Path('data/Items.json').read_text(encoding='utf8'))
rows=[]
for r in manifest['states']:
 rows.append(dict(name=r['name'],category=r['category'],description=r['description'],extra=f"{r['turns']} turns. Apply: {r['skillName']} ({round(r['chance']*100)}%).",animation=r['animation'],icon=r['icon']))
for r in manifest['removers']:
 s=skills[r['skill']];rows.append(dict(name=s['name'],category='removal',description=s['description'],extra=f"{s['mpCost']} MP. Available through class skills.",animation=s['animationId'],icon=s['iconIndex']))
html='''<!doctype html><meta charset="utf-8"><title>Conditions of Employment</title><style>body{margin:30px;background:#111e29;color:#e8f1ee;font:16px system-ui}h1{color:#f1bc68}header{max-width:1000px;line-height:1.6}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:18px}article{background:#243543;padding:16px;border:1px solid #466070;border-radius:10px}canvas{width:100%;background:#152330}p{line-height:1.5;min-height:48px}small{color:#a8c4c4}button{background:#334e60;color:white;border:1px solid #64899a;border-radius:5px;padding:9px 18px;margin:8px 8px 18px 0;cursor:pointer}.badge{font-size:12px;text-transform:uppercase;color:#e3b569}.icon{display:inline-block;width:32px;height:32px;vertical-align:middle;margin-right:12px;background-image:url('../../img/system/IconSet.png?states=v1')}h2{font-size:20px}aside{padding:20px;background:#243543;margin-top:24px}</style><header><h1>Conditions of Employment</h1><p>Twelve new battle states: biological and implant diseases, useful buffs, traditional debuffs and cybernetic interference. All expire naturally and clear at battle end. Disease effects are fictional RPG mechanics. These previews use the actual runtime animation data and show effects beside an unscaled battler.</p></header><nav><button onclick="filter('all')">All</button><button onclick="filter('disease')">Diseases</button><button onclick="filter('buff')">Buffs</button><button onclick="filter('debuff')">Debuffs</button><button onclick="filter('removal')">Removal</button><button onclick="playing=!playing">Pause / play</button></nav><main id="cards"></main><aside><h2>Newtown pharmacy and salvage dealer</h2>ITEMS</aside><script>const rows=ROWS,animations=ANIMATIONS;let playing=true,clock=0,last=0;const sheet=new Image(),actor=new Image();sheet.src='../../img/animations/ME_StateExpansion.png';actor.src='../../img/sv_actors/Rex.png';const fractureSheet=new Image();fractureSheet.src='../../img/animations/ME_ArmorFracture.png';for(const r of rows){let el=document.createElement('article');el.dataset.category=r.category;el.innerHTML='<span class="badge">'+r.category+'</span><h2><span class="icon" style="background-position:-'+r.icon%16*32+'px -'+Math.floor(r.icon/16)*32+'px"></span>'+r.name+'</h2><canvas width="384" height="180"></canvas><p>'+r.description+'</p><small>'+r.extra+'</small>';cards.append(el);r.canvas=el.querySelector('canvas')}function filter(c){document.querySelectorAll('article').forEach(e=>e.hidden=c!=='all'&&e.dataset.category!==c)}function draw(ms){if(playing)clock+=Math.min(ms-last,100);last=ms;for(const r of rows){let x=r.canvas.getContext('2d');x.clearRect(0,0,384,180);if(actor.complete&&actor.naturalWidth){let w=actor.naturalWidth/9,h=actor.naturalHeight/6;x.drawImage(actor,0,0,w,h,192-w/2,96-h/2,w,h)}let frames=animations[r.animation].frames,idx=Math.floor(clock/(1000/60*4))%(frames.length+12);let image=animations[r.animation].animation1Name==='ME_ArmorFracture'?fractureSheet:sheet;if(image.complete&&image.naturalWidth&&idx<frames.length){for(const c of frames[idx]){x.save();x.translate(192+c[1],96+c[2]);x.rotate(c[4]*Math.PI/180);x.scale(c[3]/100,c[3]/100);x.globalAlpha=c[6]/255;x.drawImage(image,c[0]%5*192,Math.floor(c[0]/5)*192,192,192,-96,-96,192,192);x.restore()}}}requestAnimationFrame(draw)}requestAnimationFrame(draw)</script>'''
itemhtml=''.join('<p><strong>'+items[r['id']]['name']+'</strong> ('+str(items[r['id']]['price'])+' gold): '+items[r['id']]['description']+'</p>' for r in manifest['items'])
html=html.replace('ITEMS',itemhtml).replace('ROWS',json.dumps(rows)).replace('ANIMATIONS',json.dumps(animations));Path('art/states/preview.html').write_text(html,encoding='utf8')
lines=['# Conditions of Employment','', 'States 52–63; player skills 199–214; enemy variants 215–226; items 157–160; native animations 188–203; icons 2016–2047.','', 'All new states use native traits, fixed turn-end duration and battle-end removal. Harmful application skills use magical hit type so normal state-rate/resist traits are honored. Beneficial applications and removals use certain hit. No battle plugins or legacy state records changed. Reapplication resets duration; states do not stack with themselves. Different states can combine.','', '| State | Effect | Turns | Apply | Remove |','|---|---|---|---|---|']
for r in manifest['states']:
 removal='Clinical Flush / Pathogen Purge' if r['category']=='disease' else ('Revoke Benefits (enemy), Safe Mode (ally) / Benefit Revocation (enemy)' if r['category']=='buff' else 'Neural Reboot / Neural Reset Cartridge')
 lines.append('|'+r['name']+'|'+r['description']+'|'+str(r['turns'])+'|'+r['skillName']+'|'+removal+'|')
lines+=['','Emergency Rollback clears all twelve new states from an ally, including buffs. Revoke Benefits and Benefit Revocation also strip native stat buffs. Removers enumerate their targets and do not remove Knockout, Immortal or unrelated scripted states. Packet Loss seals Tech only; Ability-based cures and items remain available.','', 'Class traits grant skills to existing and new saves. MP costs: applications 5–7; Clinical Flush 6; Neural Reboot 5; Revoke Benefits 6; Safe Mode 2. Shops: Map105 events 4 and 5. Prices: 60/55/75/90 gold. All items are battle consumables.','', 'Enemy variants reuse the same effect/animation/icon and intentionally cost no MP because these ordinary enemies have zero MP. They appear on turn 2 and every 4 turns thereafter, with rating 4 against ordinary attack rating 5. This leaves normal attacks available and does not touch bosses.','']
for r in manifest['states']:lines.append('- Enemy '+str(r['enemy'])+': '+r['skillName']+' ('+str(r['enemySkill'])+').')
lines+=['','Art: generated atlas.png; pack.js creates the icon and 192px-cell animation sheets. Effects use modest 12–30% scales with distinct positions/choreography, not enlarged full-screen symbols. preview.py reads live records to prevent preview/runtime drift.','', 'Build once using build.py (duplicate IDs refused). Original files are in before.zip. Test with node tools/state-expansion/test.js. Review art/states/preview.html. Validation covers native effects, resistance, duration, cures, enemy eligibility, class availability, save roundtrip and full action timing. Campaign balance still needs ordinary playtesting.']
Path('tools/state-expansion/README.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
print('Wrote live-data preview and state/application/removal reference')
